from collections import Counter

def countBalancedPairs(weight, wt):
    MOD = 10**9 + 7
    freq = Counter(weight)
    ans = 0
    if wt == 0:
        for w, c in freq.items():
            ans = (ans + c * (c - 1) // 2) % MOD
    else:
        for w, c in freq.items():
            ans = (ans + c * freq.get(w + wt, 0)) % MOD
    return ans

import java.util.*;

class Solution {
    public int countBalancedPairs(int[] weight, int wt) {
        final long MOD = 1_000_000_007L;
        Map<Integer, Long> freq = new HashMap<>();
        for (int w : weight) freq.merge(w, 1L, Long::sum);
        long ans = 0;
        if (wt == 0) {
            for (long c : freq.values()) {
                ans = (ans + c * (c - 1) / 2) % MOD;
            }
        } else {
            for (Map.Entry<Integer, Long> e : freq.entrySet()) {
                long c = e.getValue();
                long other = freq.getOrDefault(e.getKey() + wt, 0L);
                ans = (ans + c * other) % MOD;
            }
        }
        return (int) ans;
    }
}

#include <vector>
#include <unordered_map>
using namespace std;

class Solution {
public:
    int countBalancedPairs(vector<int>& weight, int wt) {
        const long long MOD = 1'000'000'007LL;
        unordered_map<int, long long> freq;
        for (int w : weight) freq[w]++;
        long long ans = 0;
        if (wt == 0) {
            for (auto& [w, c] : freq) {
                ans = (ans + c * (c - 1) / 2) % MOD;
            }
        } else {
            for (auto& [w, c] : freq) {
                auto it = freq.find(w + wt);
                if (it != freq.end()) {
                    ans = (ans + c * it->second) % MOD;
                }
            }
        }
        return (int) ans;
    }
};
